using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
// Read-only alternative hair construction study. The independent female face stays unchanged.
public static class NurseNativeHairStudy {
 static float S(float a,float b,float x){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));}
 static float verticalScale;
 static Vector3 Fit(Vector3 p){return new Vector3(p.x*.84f,1.628f+(p.y-1.71666f)*verticalScale,.005f+(p.z-.005f)*.86f);}
 static Vector3 Shape(Vector3 p){p=new Vector3(p.x*.84f,1.628f+(p.y-1.71666f)*verticalScale,.005f+(p.z-.005f)*.86f);float side=S(.035f,.070f,Mathf.Abs(p.x)),rear=1-S(-.015f,.055f,p.z),region=Mathf.Max(side,rear);float loose=S(1.70f,1.59f,p.y);p.y-=.22f*region*loose*loose;p.x+=Mathf.Sin(p.y*24+p.z*11)*.005f*loose*loose;p.z+=Mathf.Sin(p.y*19+p.x*7)*.005f*loose*loose;return p;}
 static Vector3 ShapeNormal(Vector3 p,Vector3 n){const float d=.0001f;var matrix=Matrix4x4.identity;matrix.SetColumn(0,(Shape(p+Vector3.right*d)-Shape(p-Vector3.right*d))/(2*d));matrix.SetColumn(1,(Shape(p+Vector3.up*d)-Shape(p-Vector3.up*d))/(2*d));matrix.SetColumn(2,(Shape(p+Vector3.forward*d)-Shape(p-Vector3.forward*d))/(2*d));return matrix.inverse.transpose.MultiplyVector(n).normalized;}
 public static void Run(){try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var source=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Moe/PrefabInstance/ZMoe.prefab"));source.GetComponent<Animator>().enabled=false;var native=source.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");int slot=Array.FindIndex(native.sharedMaterials,m=>m.name.IndexOf("Hair",StringComparison.OrdinalIgnoreCase)>=0);if(slot<0)throw new Exception("Native hair material slot missing");var world=NurseAnatomyRender.WorldSkin(native);var input=world.GetTriangles(slot);var ids=input.Distinct().ToArray();verticalScale=(1.747f-1.628f)/(ids.Max(i=>world.vertices[i].y)-1.71666f);var nativeMaterial=new Material(native.sharedMaterials[slot]);nativeMaterial.shader=RebirthEntityStudio.RebirthNativeShaderLibrary.Get("Game/Autodesk");nativeMaterial.name="EntityStudioHair_RebirthNurse_NativeCardStudy";nativeMaterial.shaderKeywords=new[]{"_ALPHATEST_ON","_GLOSSYREFLECTIONS_OFF","_NORMALMAP","_SPECGLOSSMAP","_SPECULARHIGHLIGHTS_OFF"};
  var sourcePoints=world.vertices;var sourceNormals=world.normals;var sourceUV=world.uv;var map=ids.Select((id,index)=>new{id,index}).ToDictionary(p=>p.id,p=>p.index);var points=ids.Select(i=>Shape(sourcePoints[i])).ToList();var normalList=ids.Select(i=>ShapeNormal(sourcePoints[i],sourceNormals[i])).ToList();var coords=ids.Select(i=>sourceUV[i]).ToList();var triangles=input.Select(i=>map[i]).ToList();
  // Short cards lie on the forehead's curved surface, with roots fixed above the brows.
  for(int card=0;card<8;card++){int start=points.Count;float root=Mathf.Lerp(-.045f,.045f,card/7f),tip=root+Mathf.Sign(root)*.010f;float rootY=1.623f+.118f*Mathf.Sqrt(Mathf.Max(.01f,1-root*root/(.074f*.074f)))-.005f,tipY=1.665f+.006f*Mathf.Sin(card*1.7f);for(int step=0;step<=10;step++){float t=step/10f;for(int cross=0;cross<3;cross++){float across=cross*.5f,x=Mathf.Lerp(root,tip,t)+(across-.5f)*.024f*Mathf.Lerp(.25f,1,S(0,.25f,t)),y=Mathf.Lerp(rootY,tipY,t);float z=.005f+.076f*Mathf.Sqrt(Mathf.Max(.01f,1-x*x/(.074f*.074f)-(y-1.623f)*(y-1.623f)/(.118f*.118f)))+.005f;var p=new Vector3(x,y,z);points.Add(p);normalList.Add(new Vector3(x/(.074f*.074f),(y-1.623f)/(.118f*.118f),(z-.005f)/(.076f*.076f)).normalized);coords.Add(new Vector2(across*.25f,1-t));}}for(int step=0;step<10;step++)for(int cross=0;cross<2;cross++){int a=start+step*3+cross,b=a+1,c=a+3,d=c+1;triangles.AddRange(new[]{a,c,b,b,c,d});}}
  UnityEngine.Object.DestroyImmediate(source);
  var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseIndependentAssembly/RebirthNurse_IndependentCandidate.prefab"));model.GetComponent<Animator>().enabled=false;model.GetComponent<LODGroup>().ForceLOD(0);RebirthEntityStudio.RebirthNurseNativeShaderPreview.Bind(model);var body=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var hidden=UnityEngine.Object.Instantiate(body.sharedMesh);hidden.SetTriangles(new int[0],1);body.sharedMesh=hidden;
  int capTriangleStart=triangles.Count;int capStart=points.Count;var capSource=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/EntityStudioGenerated/RebirthNurseHairRebuild/Hair_LOD0.asset");var capObject=new GameObject("Temporary fitted cap");var capRenderer=capObject.AddComponent<SkinnedMeshRenderer>();capRenderer.sharedMesh=capSource;capRenderer.bones=body.bones;var capWorld=NurseAnatomyRender.WorldSkin(capRenderer);var capIndices=capSource.GetTriangles(0).Take(1536*3).ToArray();int capCount=capIndices.Max()+1;for(int i=0;i<capCount;i++){points.Add(capWorld.vertices[i]);normalList.Add(capWorld.normals[i]);var coord=capSource.uv[i];float a=Mathf.InverseLerp(.04f,.085f,coord.x),b=Mathf.InverseLerp(.99f,.05f,coord.y);coords.Add(new Vector2(Mathf.Lerp(.11f,.175f,a),Mathf.Lerp(.88f,.46f,b)));}triangles.AddRange(capIndices.Select(i=>i+capStart));UnityEngine.Object.DestroyImmediate(capObject);
  var positions=points.ToArray();var normals=normalList.ToArray();var poses=body.sharedMesh.bindposes;var matrices=body.bones.Select((bone,i)=>bone.localToWorldMatrix*poses[i]).ToArray();int head=Array.FindIndex(body.bones,b=>b.name=="Head");var weights=new BoneWeight[positions.Length];float maxError=0;
  for(int i=0;i<positions.Length;i++){var desired=positions[i];float strength=i>=capStart?0:.95f*S(1.70f,1.58f,desired.y),f=Mathf.Clamp((1.65f-desired.y)/.075f,0,4);int a=Mathf.Min(3,Mathf.FloorToInt(f));float blend=f-a;int first=Array.FindIndex(body.bones,b=>b.name=="Hair_Back_Left"+(a==0?"":a.ToString())),second=Array.FindIndex(body.bones,b=>b.name=="Hair_Back_Left"+(a+1));if(head<0||first<0||second<0)throw new Exception("Existing hair bones missing");var w=new BoneWeight{boneIndex0=head,weight0=1-strength,boneIndex1=first,weight1=strength*(1-blend),boneIndex2=second,weight2=strength*blend};weights[i]=w;var skin=Matrix4x4.zero;int[] bones={head,first,second};float[] amounts={w.weight0,w.weight1,w.weight2};for(int k=0;k<3;k++)for(int row=0;row<4;row++)for(int col=0;col<4;col++)skin[row,col]+=matrices[bones[k]][row,col]*amounts[k];positions[i]=skin.inverse.MultiplyPoint3x4(desired);normals[i]=skin.inverse.MultiplyVector(normals[i]).normalized;maxError=Mathf.Max(maxError,Vector3.Distance(desired,skin.MultiplyPoint3x4(positions[i])));}
  var mesh=new Mesh{name="NativeCardHairStudy",vertices=positions,normals=normals,uv=coords.ToArray(),boneWeights=weights,bindposes=poses,triangles=triangles.ToArray()};mesh.subMeshCount=2;mesh.SetTriangles(triangles.Take(capTriangleStart).ToArray(),0);mesh.SetTriangles(triangles.Skip(capTriangleStart).ToArray(),1);mesh.RecalculateTangents();mesh.RecalculateBounds();var child=new GameObject("NativeCardHairStudy");child.transform.SetParent(body.transform,false);var renderer=child.AddComponent<SkinnedMeshRenderer>();renderer.sharedMesh=mesh;var capMaterial=new Material(nativeMaterial);capMaterial.SetFloat("_Cutoff",0);capMaterial.SetColor("_Color",new Color(.4f,.4f,.4f,1));renderer.sharedMaterials=new[]{nativeMaterial,capMaterial};renderer.bones=body.bones;renderer.rootBone=body.rootBone;renderer.updateWhenOffscreen=true;
  foreach(int angle in new[]{0,-30,30,180}){model.transform.rotation=Quaternion.Euler(0,angle,0);NurseVisualOptimization.Render(model,"NativeCardsFace_"+angle,0,true,true);}nativeMaterial.SetColor("_Color",new Color(3f,2.2f,1.6f,1));capMaterial.SetColor("_Color",new Color(1.2f,.88f,.64f,1));foreach(int angle in new[]{0,30}){model.transform.rotation=Quaternion.Euler(0,angle,0);NurseVisualOptimization.Render(model,"NativeCardsWarmFace_"+angle,0,true,true);}model.transform.rotation=Quaternion.identity;NurseVisualOptimization.Render(model,"NativeCardsBody",0,false,true);File.WriteAllText(NurseVisualOptimization.Out+"/native-hair-card-study.txt","Actual native hair submesh only, vertically fitted and side/back locks lengthened; original native hair UV/maps retained. No Moe face vertices, facial textures or body surfaces copied. Independent female head unchanged. Native hair triangles="+input.Length/3+"; vertices="+ids.Length+"; vertical fit scale="+verticalScale+"; bind reconstruction error="+maxError+"m. Existing Head/hair chain only. Read-only study, not installed.\n");Debug.Log("NURSE_NATIVE_HAIR_STUDY_READY");
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
